window.__CAT__=window.__CAT__||[];window.__CAT__.push([{"no": 72, "id": "9yF3PUnhQAU", "title": "【Lの女性向音声】从第一眼见你，就认定了，你是我哥哥！", "title_zh": "从第一眼见你，就认定了，你是我哥哥！", "duration": "00:06:35", "link": "https://www.youtube.com/watch?v=9yF3PUnhQAU", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我说了不要再跟着我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "我不是你哥哥。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "你是不是应该去找一找，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "你真正的家人。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:13", "text": "我只是你的主治医生。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:16", "text": "并不需要，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:23", "text": "我也不会负责你的人生的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "无家可归啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:37", "text": "那我帮你联系一下警察，好吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "放手啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "你这样抓着我的，会影响我工作的。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:00:58", "text": "这样吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "看见你这样一直不走了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "坐在那儿，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "乖乖等我回来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "好吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "到时候，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "我会叫护士来陪你的。", "speaker": "哥哥", "tone": "温柔", "sound": []}, {"ts": "00:01:21", "text": "好吧？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "等我下班了，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "我们再来讨论怎么处理你的事情。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "既然，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "确实没办法联系你的家人。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "那你暂时跟我回家吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "还有，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "不许叫我哥哥。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:39", "text": "我跟你说。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "不许叫我哥哥。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:01:42-00:02:00", "text": "（音频转写失真，已压缩）。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:02", "text": "我跟你没有任何关系。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "都说了不准叫哥哥。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:02:11", "text": "走吧走吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "到家了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "进来吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "这里没有你的卧室啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:39", "text": "这是我家。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "不要这么看着我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "你现在只是暂住。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "从现在开始，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "一切都得听我的。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:02:52", "text": "知道了吗？", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:02:55", "text": "好。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:02:57", "text": "既然知道了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "那第一件事，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "就是把你，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "像妈妈，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "一样的眼神，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:09", "text": "给我换掉。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:11", "text": "然后我下面说的话，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:14", "text": "你要全部记清楚。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "那个靠近厨房的房间，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:23", "text": "就是允许你暂住的房间。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "除了这个，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:28", "text": "还有卫生间以外的房间，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:31", "text": "都不可以进去。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:34", "text": "厨房。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:03:37", "text": "你会做饭吗？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "不会就不要去添乱了。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:03:45", "text": "然后。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "我这也没有你用的东西啊！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:52", "text": "一会儿你陪我去趟超市。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "顺便买点生活用品。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "自己挑你需要的东西。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "还有。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:05", "text": "要拿小票。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:08", "text": "我不是做慈善。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "等找到家人之后，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "通通还给我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:19", "text": "今天就先这样吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:22", "text": "东西放在哪里，", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:26", "text": "我都会告诉你。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "如果有事情，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:34", "text": "就敲我的门。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "不要这样看着我。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:40", "text": "当然不可以进我的房间啊！", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:04:43", "text": "不记得我刚才说的话了？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "在我家都听我的。", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:04:56", "text": "现在去洗漱。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:04:59", "text": "睡觉。", "speaker": "哥哥", "tone": "宠溺", "sound": []}, {"ts": "00:05:03", "text": "快。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "听话。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:10", "text": "终于可以休息了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "真的谢天谢地啊！", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:25", "text": "明天。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:28", "text": "明天还是要联系一下主治。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:32", "text": "这样就把人塞给我了。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "进来。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:43", "text": "睡不着？", "speaker": "哥哥", "tone": "命令", "sound": []}, {"ts": "00:05:49", "text": "你以为是三岁小孩吗？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "我真是。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:00", "text": "真是捡了个小祖宗。", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:04", "text": "哎呀！", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:09", "text": "不过，会想到以前，", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:14", "text": "那么骄纵的人，", "speaker": "哥哥", "tone": "撒娇", "sound": []}, {"ts": "00:06:17", "text": "会乖乖跟我回家呢？", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:20", "text": "只有这几天晚上。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:23", "text": "记住了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:26", "text": "进来吧。", "speaker": "哥哥", "tone": "平静", "sound": []}, {"ts": "00:06:30", "text": "记住了吗？", "speaker": "哥哥", "tone": "询问", "sound": []}, {"ts": "00:06:34", "text": "进来吧。", "speaker": "哥哥", "tone": "平静", "sound": []}], "scene": "无家可归的女孩缠着她的「主治医生」叫哥哥，医生拒绝负责、先想联系警察，最终心软带她回自己家暂住（「赞助」=寄住）。他立规矩：不准叫哥哥、限定活动房间、陪她去超市买日用品并保留小票、洗澡睡觉；夜里你睡不着又进来，他无奈叹气「小祖宗」。整体是「拒绝→心软收留 + 立规矩」型日常角色扮演，基调驯顺、domestic、带监护感。", "behaviors": [{"desc": "「我说了不要再跟着我 我不是你哥哥」，拒绝"}, {"desc": "「那我帮你联系一下警察」，想报警"}, {"desc": "「坐在那 快快等我回来」，让你坐等"}, {"desc": "「既然没办法联系家人 那你再实现跟我回家吧」，带回家"}, {"desc": "「到家了 到我家了」，进家门"}, {"desc": "「你现在只是赞助 一切听我的」，立规矩"}, {"desc": "「靠近出房的房间 就是允许你赞助的房间」，指定可住房间"}, {"desc": "「一会儿你陪我去趟超市」，带你去超市买日用品"}, {"desc": "「现在去洗澡（洗澡）睡觉」，让你洗澡"}, {"desc": "「进来」，你夜里又进来"}, {"desc": "「我真是 记了个小祖宗」，无奈叹气"}, {"desc": "「进来吧」，让你进房间"}], "tone_summary": "（自动）哥哥视角独白，语气以平静、命令、询问为主，题材偏医疗。", "genre_tags": ["医疗", "治愈"], "genre_main": "医疗", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被哥哥倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "医院走廊里，他快步走在前面，身后那个女孩小跑着跟上来，伸手拽住他的白大褂。他停下脚步，回头看她，语气带着无奈。"}, {"type": "line", "speaker": "哥哥", "text": "我说了不要再跟着我。我不是你哥哥。你是不是应该去找一找，你真正的家人。我只是你的主治医生。并不需要，我也不会负责你的人生的。"}, {"type": "narr", "text": "她低下头，小声说，我无家可归。他看着她，沉默了一瞬，还是拿出手机。"}, {"type": "line", "speaker": "哥哥", "text": "无家可归啊！那我帮你联系一下警察，好吧？放手啊！你这样抓着我的，会影响我工作的。"}, {"type": "narr", "text": "她不肯放，眼眶红红的。他叹了口气，看了看周围，妥协地指了指候诊区的椅子。"}, {"type": "line", "speaker": "哥哥", "text": "这样吧。看见你这样一直不走了。坐在那儿，乖乖等我回来。好吧？到时候，我会叫护士来陪你的。好吧？等我下班了，我们再来讨论怎么处理你的事情。"}, {"type": "narr", "text": "下班时，他到底还是没能把她交给警察。她站在医院门口，像一只被雨淋湿的小猫，可怜巴巴地看着他。他揉了揉眉心，妥协了。"}, {"type": "line", "speaker": "哥哥", "text": "既然，确实没办法联系你的家人。那你暂时跟我回家吧。还有，不许叫我哥哥。我跟你说。不许叫我哥哥。"}, {"type": "narr", "text": "她亦步亦趋地跟着他回家，路上偷偷抬眼看他，小声喊了一句哥哥。他脚步一顿，回头瞪她。"}, {"type": "line", "speaker": "哥哥", "text": "我跟你没有任何关系。都说了不准叫哥哥。走吧走吧。"}, {"type": "narr", "text": "到家，他打开门，她站在玄关，好奇地打量着陌生的屋子。他回头，语气带着严肃的声明。"}, {"type": "line", "speaker": "哥哥", "text": "到家了。进来吧。这里没有你的卧室啊！这是我家。不要这么看着我。你现在只是暂住。从现在开始，一切都得听我的。知道了吗？好。既然知道了。那第一件事，就是把你，像妈妈，一样的眼神，给我换掉。"}, {"type": "narr", "text": "她立刻收起那副湿漉漉的眼神，站得端端正正。他满意地点点头，开始说规矩。"}, {"type": "line", "speaker": "哥哥", "text": "然后我下面说的话，你要全部记清楚。那个靠近厨房的房间，就是允许你暂住的房间。除了这个，还有卫生间以外的房间，都不可以进去。"}, {"type": "line", "speaker": "哥哥", "text": "厨房。你会做饭吗？不会就不要去添乱了。然后。我这也没有你用的东西啊！一会儿你陪我去趟超市。顺便买点生活用品。自己挑你需要的东西。还有。要拿小票。我不是做慈善。等找到家人之后，通通还给我。"}, {"type": "narr", "text": "她乖乖点头。他看着她，声音顿了顿，语气缓和了些。"}, {"type": "line", "speaker": "哥哥", "text": "今天就先这样吧。东西放在哪里，我都会告诉你。如果有事情，就敲我的门。不要这样看着我。当然不可以进我的房间啊！不记得我刚才说的话了？在我家都听我的。现在去洗漱。睡觉。快。听话。"}, {"type": "narr", "text": "深夜，他关上门，终于松口气，靠在门板上揉了揉太阳穴。回想这一天，还是觉得荒诞。"}, {"type": "line", "speaker": "哥哥", "text": "终于可以休息了。真的谢天谢地啊！明天。明天还是要联系一下主治。这样就把人塞给我了。"}, {"type": "narr", "text": "门外忽然传来轻轻的敲门声。他皱眉，走过去开门，看见她抱着枕头站在门口，一脸不安。"}, {"type": "line", "speaker": "哥哥", "text": "进来。睡不着？你以为是三岁小孩吗？我真是。真是捡了个小祖宗。哎呀！"}, {"type": "narr", "text": "他嘴上嫌弃，却还是侧身让她进来，替她铺好沙发。她裹着毯子，小声说了句谢谢。他背对着她，没有回头，语气却带着一丝认命的温柔。"}, {"type": "line", "speaker": "哥哥", "text": "不过，会想到以前，那么骄纵的人，会乖乖跟我回家呢？只有这几天晚上。记住了吗？进来吧。记住了吗？进来吧。"}, {"type": "narr", "text": "夜灯亮着，她在沙发上蜷成小小一团，渐渐睡熟了。他看着她的睡颜，想起白天她拽着他白大褂的样子，轻轻叹了口气。这个家里，好像忽然多了一点什么。而那句“不许叫哥哥”，大概很快就会作废。"}]}, {"no": 73, "id": "K1Z4xVb7TwM", "title": "【Lの女性向音声】他的引导", "title_zh": "他的引导", "duration": "00:05:01", "link": "https://www.youtube.com/watch?v=K1Z4xVb7TwM", "enriched": true, "lines": [{"ts": "00:00:00", "text": "为什么今天过来了？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:00:05", "text": "说好，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "只有约定好的日子可以过来找我。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:00:15", "text": "当初答应你，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:20", "text": "是相信你不会胡闹任性，", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:00:25", "text": "是个会遵守约定的好孩子。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:31", "text": "过来吧。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:00:34", "text": "来都来了，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "我不会赶你走的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "怎么了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "下午就一直说想见我，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "心情不好？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:51", "text": "只是想我了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "你知道吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:00:58", "text": "你撒谎的时候，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "总是会不自觉地低头，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:04", "text": "不敢看我的眼睛。", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:01:08", "text": "过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:11", "text": "靠过来。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:15", "text": "怎么了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:18", "text": "家里说什么了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "我爸爸妈妈吵架了？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "这有什么难为情的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:28", "text": "每个家庭，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:32", "text": "多多少少都会有些问题和矛盾。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:35", "text": "爸爸妈妈分开久了，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "在很多事情上意见有分歧，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "他们没有办法理解你的生活，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "你也没有办法去理解他们的期待。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:49", "text": "再正常不过了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "其实你已经很努力了，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "真的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:58", "text": "不需要因为没有满足他们的期待，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:01", "text": "感到难过。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:04", "text": "你在很努力地过好你的生活，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "这一件做得很好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:13", "text": "你没有很差，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "你也没有比别人差。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:18", "text": "你很聪明的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:21", "text": "这些事情不用我开导，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:24", "text": "其实你也应该懂得。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:27", "text": "所以如果你，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "还是觉得难过的话，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "我觉得，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:36", "text": "应该是你没有满足，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:39", "text": "你对自己的期待。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "你说是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "如果你想再努力一点，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:47", "text": "追求自己的目标，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "做自己喜欢的事。", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:02:52", "text": "我不会阻拦你的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "而且会支持你的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "懂吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:03:00", "text": "抓住我。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "握紧。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:05", "text": "不要害怕。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:07", "text": "很多事情事实上，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "并没有你想得那么困难。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "我很早就说过。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "如果你愿意，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:18", "text": "除了约定的关系，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "任何地方我能帮你的，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:24", "text": "你可以随时来找我。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:27", "text": "只是。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:29", "text": "一年了，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:32", "text": "你也没来找过我什么？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "这还是你第一次，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:38", "text": "和我说家里的事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "我们俩虽然，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:43", "text": "不是一般的亲密关系，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "我不会像，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "一个男朋友一样，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "那么照顾你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "但如果你，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "遇到什么困难的事，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "就来找我吧。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:57", "text": "以后不用在约定好的固定时间，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:02", "text": "想过来就随时过来吧。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:04:07", "text": "小姑娘。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:11", "text": "也不用太懂规矩了。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:15", "text": "我说过的话，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:18", "text": "不要让我解释原因，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:21", "text": "也不要让我重复第二遍。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:24-00:04:27", "text": "不用担心打扰我。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:30", "text": "你不会成为打扰的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:33", "text": "今天还想要惩罚吗？", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:04:37", "text": "那好。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "你听着。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "今天我不会罚你，", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:37", "text": "这段时间都不会再罚你。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:37", "text": "直到你不会再说，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "觉得自己很差这种话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "什么时候学会了，", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "什么时候再来找我要惩罚。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:37", "text": "我会看着你的。", "speaker": "爸爸", "tone": "平静", "sound": []}], "scene": "你们是「约定关系」的引导者与被引导者。你破例在非约定日找他，因父母吵架心情低落；他让你靠过来，温和开导你「已很努力、不比任何人差」，支持你追求目标，并打破固定见面时间、随时可来；最后说这段时间不再罚你，等你学会不再自我否定再来「要成长（成法）」。整体是「温柔引导 + 心理支持」型角色扮演，基调治愈、dom/sub 偏导师。", "behaviors": [{"desc": "「说好只有约定好的日子可以过来」，指出你破例"}, {"desc": "「过来吧 来都来了 我不会赶你走」，让你过来"}, {"desc": "「你撒谎时 总是不辞决低头 不敢看我眼睛」，看穿你撒谎"}, {"desc": "「过来 靠过来」，让你靠过来"}, {"desc": "开导你父母吵架很正常，你已很努力"}, {"desc": "「如果你想再努力 抓住我 握紧」，让你握手"}, {"desc": "「这还是你第一次和我说家里的事」"}, {"desc": "「以后不用固定时间 想过来随时过来」，放宽见面规矩"}, {"desc": "「今天还想要成法吗」，问是否要惩罚"}, {"desc": "「今天我不会罚你 直到你不会说自己很差」，暂停惩罚"}], "tone_summary": "（自动）爸爸视角独白，语气以平静、命令、责备为主，题材偏古风。", "genre_tags": ["古风", "家庭/长辈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被爸爸倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门铃响起的时候，他放下手里的书，微微皱了皱眉——今天并不是约定的日子。门外，她低着头站在那里，绞着手指，像一只犯了错又无处可去的小动物。"}, {"type": "line", "speaker": "爸爸", "text": "为什么今天过来了？说好，只有约定好的日子可以过来找我。当初答应你，是相信你不会胡闹任性，是个会遵守约定的好孩子。"}, {"type": "narr", "text": "她头埋得更低了，声音带着一点委屈的鼻音。他看着她，终究叹了口气，侧身让开门口。"}, {"type": "line", "speaker": "爸爸", "text": "过来吧。来都来了，我不会赶你走的。怎么了？下午就一直说想见我，心情不好？只是想我了？"}, {"type": "narr", "text": "她小声说，就是有点想爸爸了。他看着她闪躲的眼神，语气平静却笃定。"}, {"type": "line", "speaker": "爸爸", "text": "你知道吗？你撒谎的时候，总是会不自觉地低头，不敢看我的眼睛。过来。靠过来。怎么了？家里说什么了？"}, {"type": "line", "speaker": "爸爸", "text": "我爸爸妈妈吵架了？这有什么难为情的。每个家庭，多多少少都会有些问题和矛盾。"}, {"type": "narr", "text": "她靠在他肩头，眼泪无声地掉下来。他没有打断她，只是轻轻拍着她的背，声音温和而沉稳。"}, {"type": "line", "speaker": "爸爸", "text": "爸爸妈妈分开久了，在很多事情上意见有分歧，他们没有办法理解你的生活，你也没有办法去理解他们的期待。再正常不过了。"}, {"type": "narr", "text": "她闷闷地说，觉得自己让他们失望了。他低头看着她，语气带着认真的温柔。"}, {"type": "line", "speaker": "爸爸", "text": "其实你已经很努力了，真的。不需要因为没有满足他们的期待，感到难过。你在很努力地过好你的生活，这一件做得很好。"}, {"type": "line", "speaker": "爸爸", "text": "你没有很差，你也没有比别人差。你很聪明的。这些事情不用我开导，其实你也应该懂得。所以如果你，还是觉得难过的话，我觉得，应该是你没有满足，你对自己的期待。你说是不是？"}, {"type": "narr", "text": "她安静下来，像是在认真想他的话。他看着她，语气带着鼓励。"}, {"type": "line", "speaker": "爸爸", "text": "如果你想再努力一点，追求自己的目标，做自己喜欢的事。我不会阻拦你的。而且会支持你的。懂吗？"}, {"type": "line", "speaker": "爸爸", "text": "抓住我。握紧。不要害怕。很多事情事实上，并没有你想得那么困难。我很早就说过。如果你愿意，除了约定的关系，任何地方我能帮你的，你可以随时来找我。"}, {"type": "narr", "text": "她伸出手，轻轻抓住他的手指。他反手握住，力道稳而暖。他顿了顿，语气带着一点感慨。"}, {"type": "line", "speaker": "爸爸", "text": "只是。一年了，你也没来找过我什么？这还是你第一次，和我说家里的事。我们俩虽然，不是一般的亲密关系，我不会像，一个男朋友一样，那么照顾你。"}, {"type": "line", "speaker": "爸爸", "text": "但如果你，遇到什么困难的事，就来找我吧。以后不用在约定好的固定时间，想过来就随时过来吧。小姑娘。也不用太懂规矩了。"}, {"type": "narr", "text": "她抬起头，眼睛亮了一下。他看着她，语气带着不容置疑的温和。"}, {"type": "line", "speaker": "爸爸", "text": "我说过的话，不要让我解释原因，也不要让我重复第二遍。不用担心打扰我。你不会成为打扰的。"}, {"type": "narr", "text": "她轻轻嗯了一声。他看着她，忽然问了一句。她怔了一下，小声说，想要。他摇了摇头，语气却格外认真。"}, {"type": "line", "speaker": "爸爸", "text": "今天还想要惩罚吗？那好。你听着。今天我不会罚你，这段时间都不会再罚你。直到你不会再说，觉得自己很差这种话。"}, {"type": "narr", "text": "她愣愣地看着他。他看着她，一字一句地说完最后的话，目光里带着她从未见过的认真。"}, {"type": "line", "speaker": "爸爸", "text": "什么时候学会了，什么时候再来找我要惩罚。我会看着你的。"}, {"type": "narr", "text": "窗外的光落进来，她忽然觉得，那句“我会看着你的”，比任何一顿惩罚都更有力量。原来被人在意，是这个样子的。"}]}, {"no": 74, "id": "KKQ3kck3Ngs", "title": "【Lの女性向音声】他的引导", "title_zh": "他的引导", "duration": "00:04:59", "link": "https://www.youtube.com/watch?v=KKQ3kck3Ngs", "enriched": true, "lines": [{"ts": "00:00:00", "text": "为什么今天过来了？说好只有约定好的日子才能来找我。当初答应你，是相信你是个会守约定的好孩子，不会胡闹任性。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:00:19", "text": "过来吧，来都来了，我不会赶你走的。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:00:38", "text": "怎么了，下午就一直说想见我，心情不好？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "只是想我了？你知道吗，你说谎的时候，总是不敢看我的眼睛。低下头，是想藏什么？", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:01:01", "text": "过来，靠过来，别站那么远。家里又说什么了？", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:01:13", "text": "我爸爸妈妈吵架了？这有什么难为情的，每个家庭多多少少都会有些问题和矛盾。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:24", "text": "爸爸妈妈分开久了，在很多事情上意见有分歧，他们没有办法理解你的生活，你也没有办法理解他们的期待。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "再正常不过了。其实你已经很努力了，真的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "不需要因为没有满足他们的期待，就感到难过。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "你在很努力地过好你的生活，这件事做得很好。", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:02:10", "text": "你没有很差，你也没有比别人差。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:02:19", "text": "你很聪明的，这些事情不用我开导，其实你也应该懂的。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:28", "text": "所以如果你还是觉得难过的话，我觉得是你没有满足你对自己的期待，你说是不是？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "如果你想再努力一点，追求自己的目标，做自己喜欢的事。", "speaker": "爸爸", "tone": "宠溺", "sound": []}, {"ts": "00:02:47", "text": "我不会拦你，还会支持你，懂吗？抓住我的手。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:02:57", "text": "握紧，别怕。很多事没你想的那么困难，有我在。", "speaker": "爸爸", "tone": "温柔", "sound": []}, {"ts": "00:03:06", "text": "我早就说过，除了约定的关系，任何我能帮你的地方，你都可以随时来找我。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "只是一年了，你也没来找过我什么？", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:25", "text": "这还是你第一次和我说家里的事。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "我们之间不是普通的亲密关系，我不会像男朋友那样惯着你。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "但如果你遇到什么困难的事，就来找我吧。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "以后不用再等约定好的固定时间，想过来就随时过来吧。", "speaker": "爸爸", "tone": "命令", "sound": []}, {"ts": "00:04:05", "text": "小姑娘，在我这儿，不用太懂规矩。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "我说过的话，不需要解释原因，也不要让我说第二遍。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "不用担心打扰我，你不会打扰到我的。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:12", "text": "今天，还想要惩罚吗？想要的话，就自己开口。", "speaker": "爸爸", "tone": "询问", "sound": []}, {"ts": "00:04:12", "text": "那好，你听着，今天我不会罚你，这段时间都不会再罚你。", "speaker": "爸爸", "tone": "责备", "sound": []}, {"ts": "00:04:12", "text": "直到你不会再说，觉得自己很差这种话。", "speaker": "爸爸", "tone": "平静", "sound": []}, {"ts": "00:04:12", "text": "什么时候学会不贬低自己了，什么时候再来找我。惩罚，我会一直给你留着，等着你。", "speaker": "爸爸", "tone": "责备", "sound": []}], "scene": "与 K1Z4xVb7TwM 同一「引导者与被引导者」设定的另一版录音。你破例在非约定日找他，因父母吵架心情低落；他让你靠过来，温和开导你「已很努力、不比任何人差」，支持你追求目标，打破固定见面时间、随时可来；最后说这段时间不再罚你，等你学会不再自我否定再来「要成法（成长）」。整体是「温柔引导 + 心理支持」型角色扮演，基调治愈、dom/sub 偏导师。", "behaviors": [{"desc": "「说好只有约定好的日子可以过来」，指出你破例"}, {"desc": "「怎么了 下午就一直说想见我 心情不好」，问你缘由"}, {"desc": "「你撒谎时 总是不刺激的头 不敢看我眼睛」，看穿你撒谎"}, {"desc": "「过来 靠过来」，让你靠过来"}, {"desc": "「你在很努力过好生活 做得很好」，肯定你"}, {"desc": "「你没有很差 抓住我 握紧」，让你握手"}, {"desc": "「以后不用固定时间 想过来随时来」，放宽规矩"}, {"desc": "「不用担心打扰我」，安抚你"}, {"desc": "「今天还想要成为吗」，问是否要惩罚"}, {"desc": "「今天我不会罚你 直到你不会说自己很差」，暂停惩罚"}], "tone_summary": "（自动）爸爸视角独白，语气以平静、命令、责备为主，题材偏古风。", "genre_tags": ["古风", "家庭/长辈"], "genre_main": "古风", "emotion_arc": "（自动）平静", "intensity": "中偏高", "listener_role": "（自动）被爸爸倾诉/照顾/管教的一方（你）", "signature_elements": ["惩罚"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "门铃响时，他放下书，微微皱眉——今天不是约定的日子。门外，她低着头，像一只无处可去的小动物。他叹了口气，侧身让开。"}, {"type": "line", "speaker": "爸爸", "text": "为什么今天过来了？说好只有约定好的日子才能来找我。当初答应你，是相信你是个会守约定的好孩子，不会胡闹任性。过来吧，来都来了，我不会赶你走的。怎么了，下午就一直说想见我，心情不好？只是想我了？"}, {"type": "narr", "text": "她小声说，就是有点想爸爸。他看着她闪躲的眼神，语气平静却笃定。"}, {"type": "line", "speaker": "爸爸", "text": "你知道吗，你说谎的时候，总是不敢看我的眼睛。低下头，是想藏什么？过来，靠过来，别站那么远。家里又说什么了？我爸爸妈妈吵架了？这有什么难为情的，每个家庭多多少少都会有些问题和矛盾。"}, {"type": "narr", "text": "她靠在他肩头，眼泪无声地掉下来。他轻轻拍着她的背，声音温和而沉稳。"}, {"type": "line", "speaker": "爸爸", "text": "爸爸妈妈分开久了，在很多事情上意见有分歧，他们没有办法理解你的生活，你也没有办法理解他们的期待。再正常不过了。其实你已经很努力了，真的。不需要因为没有满足他们的期待，就感到难过。你在很努力地过好你的生活，这件事做得很好。"}, {"type": "narr", "text": "她闷闷地说，觉得自己让他们失望了。他低头看着她，语气带着认真的温柔。"}, {"type": "line", "speaker": "爸爸", "text": "你没有很差，你也没有比别人差。你很聪明的，这些事情不用我开导，其实你也应该懂的。所以如果你还是觉得难过的话，我觉得是你没有满足你对自己的期待，你说是不是？如果你想再努力一点，追求自己的目标，做自己喜欢的事。我不会拦你，还会支持你，懂吗？抓住我的手。握紧，别怕。很多事没你想的那么困难，有我在。"}, {"type": "narr", "text": "她伸出手，轻轻握住他的手指。他反手握住，力道稳而暖，语气带着一点感慨。"}, {"type": "line", "speaker": "爸爸", "text": "我早就说过，除了约定的关系，任何我能帮你的地方，你都可以随时来找我。只是一年了，你也没来找过我什么？这还是你第一次和我说家里的事。我们之间不是普通的亲密关系，我不会像男朋友那样惯着你。但如果你遇到什么困难的事，就来找我吧。以后不用再等约定好的固定时间，想过来就随时过来吧。小姑娘，在我这儿，不用太懂规矩。我说过的话，不需要解释原因，也不要让我说第二遍。不用担心打扰我，你不会打扰到我的。"}, {"type": "narr", "text": "她轻轻嗯了一声。他看着她，忽然问了一句。她怔了一下，小声说，想要。他摇了摇头，语气却格外认真。"}, {"type": "line", "speaker": "爸爸", "text": "今天，还想要惩罚吗？想要的话，就自己开口。那好，你听着，今天我不会罚你，这段时间都不会再罚你。直到你不会再说，觉得自己很差这种话。什么时候学会不贬低自己了，什么时候再来找我。惩罚，我会一直给你留着，等着你。"}, {"type": "narr", "text": "窗外的光落进来，她忽然觉得，那句“等着你”，比任何一顿惩罚都更有力量。原来被人在意，是这个样子的。"}]}, {"no": 75, "id": "LcR8X5uxy9E", "title": "【Lの女性向音声】你呀，是主人最疼爱的宝贝", "title_zh": "你呀，是主人最疼爱的宝贝", "duration": "00:09:02", "link": "https://www.youtube.com/watch?v=LcR8X5uxy9E", "enriched": true, "lines": [{"ts": "00:00:00", "text": "爸爸，是我，我回来了。家里怎么这么暗？你不是怕黑吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:29", "text": "怎么哭得这么厉害？爸爸，发生什么事了？主人不是在这儿，紧紧抱着你吗？乖。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:00:58", "text": "这会儿先放下，让主人帮你处理，咱们慢慢说。不哭了，爸爸，不哭了。你都哭得快喘不过气了，不哭了，不哭了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:28", "text": "现在刚过中午不久。可是昨晚通电话时，爸爸的状态听上去不太好，最后还是哄你睡着了吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "可主人还是担心。今天早上起来没收到你消息，电话也拨不通。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:56", "text": "所以工作那边交代他们收尾，我就先赶回来了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:11", "text": "做了个梦，醒来之后发现电话坏了，没法打电话，还生气了是不是？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "嗯，最后就一直把自己锁在房间里了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "我能体会。我知道爸爸不敢睡觉，不是你的错。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:56", "text": "感觉世界没有声音也没有颜色，只剩你一个人了？不会的，宝贝。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:03:10", "text": "现在不怕，主人陪着你呢。", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:25", "text": "梦到什么了呀？眼泪怎么又掉下来了，这样眼睛会哭坏的。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:03:42", "text": "不着急，慢慢说。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:54", "text": "梦到我不回来了？傻孩子，主人一定不会丢下宝宝一个人的。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:04:06", "text": "嗯，就算和上次一样，因为工作或其他原因，需要出门比较久——", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:18", "text": "我也一定会在和宝宝约定的时间回来。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:04:30", "text": "为什么要说对不起？宝宝没有给我添麻烦，这个星期啊——", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:04:46", "text": "宝贝已经很勇敢、很坚强，每天都努力照顾自己，不让主人担心。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:05:02", "text": "但是你这样……手怎么了？伸过来我看看。没什么就伸过来，另一只也伸过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:18", "text": "手上压印全都是，不光这几个伤口还渗着血，还说没什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "我都不知道你压得这么厉害，疼不疼？还摇头。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:50", "text": "你这样子，说不疼，却一点力气都没有。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:06:06", "text": "主人知道，我的宝宝不是故意的，已经很努力想控制自己了。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:06:20", "text": "今天没打算烦你。可是宝贝啊，主人希望你知道，我的宝宝是很优秀、很优秀的小朋友。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:06:35", "text": "所以你可以再相信自己一点，相信自己能留在主人身边。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:50", "text": "你这个样子，我看了真的好心疼好心疼。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:07:05", "text": "好好待着，我去给你拿冰块。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:21", "text": "拿个冰块，一分钟，一分钟就回来，好吧，乖。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:07:38", "text": "还是跟过来了，小傻瓜。主人不会不见的，来，坐过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:07:55", "text": "给你敷上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:09", "text": "我去把你衣角抚平，你到椅子上去，乖乖坐着，听到了没？", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:08:24", "text": "眼睛里都是血丝，还一眨不眨地盯着我看。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:38", "text": "等酒喝完，乖乖把药吃了，然后和主人一起，好好吃一会儿。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:08:53", "text": "醒来以后我还在，保证宝宝一睁眼，真的就能看见我，好不好？", "speaker": "主人", "tone": "撒娇", "sound": []}], "scene": "主人赶回家，发现你（自称「抱抱/宝宝」）因做噩梦梦到他不回来、电话又坏、把自己锁在床上、怕黑而崩溃大哭，手上还有自伤的压印和血痕。他紧紧抱你、擦泪、查看伤口、拿冰块敷、喂药吃饭、一遍遍保证「不会丢下你」，最后哄你睡并承诺醒来他还在。整体是「崩溃安抚 + 守护」型角色扮演，基调极治愈、心疼、domestic。", "behaviors": [{"desc": "你哭得厉害，他进门紧抱「这不是紧紧抱着你了吗」"}, {"desc": "「昨天通电话状态不好 今天没收到消息 电话播不通 就赶回来」，解释赶回"}, {"desc": "「我知道抱抱不敢睡觉」，安抚你"}, {"desc": "「现在不怕 主人陪着你呢」，抱紧你"}, {"desc": "「梦到什么了呀 眼泪又掉下来了」，问你噩梦"}, {"desc": "「手怎么了 身过了我看看」，查看手上压印与流血伤口"}, {"desc": "「我的宝宝不是故意的 很有秀（优秀）」，安抚你"}, {"desc": "「我去给你拿冰块 一分钟就回来」，去拿冰块"}, {"desc": "「给你附上（敷上） 你去到椅子上 乖乖坐着」，敷伤并让你坐好"}, {"desc": "「喝完酒（药）之后 乖乖把药吃了」，喂你吃药"}, {"desc": "「醒来以后 我还会在的」，哄睡并保证醒来他还在"}], "tone_summary": "（自动）主人视角独白，语气以平静、撒娇、命令为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "家庭/长辈", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静→撒娇", "intensity": "轻", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "他推开家门，屋里暗沉沉的。房间里传来压抑的抽泣声。他快步走进去，看见她蜷在角落，眼眶红肿，手上还有深深浅浅的压痕。他心里一紧，却先放软了声音。"}, {"type": "line", "speaker": "主人", "text": "爸爸，是我，我回来了。家里怎么这么暗？你不是怕黑吗？怎么哭得这么厉害？爸爸，发生什么事了？主人不是在这儿，紧紧抱着你吗？乖。这会儿先放下，让主人帮你处理，咱们慢慢说。不哭了，爸爸，不哭了。你都哭得快喘不过气了，不哭了，不哭了。"}, {"type": "narr", "text": "她在他怀里抖得厉害，声音断断续续。他轻轻拍着她的背，一下一下，像是要把她心里的恐惧都抚平。"}, {"type": "line", "speaker": "主人", "text": "现在刚过中午不久。可是昨晚通电话时，爸爸的状态听上去不太好，最后还是哄你睡着了吧。可主人还是担心。今天早上起来没收到你消息，电话也拨不通。所以工作那边交代他们收尾，我就先赶回来了。做了个梦，醒来之后发现电话坏了，没法打电话，还生气了是不是？嗯，最后就一直把自己锁在房间里了。"}, {"type": "narr", "text": "她靠在他怀里，眼泪无声地淌。他低头看着她，声音带着心疼的理解。"}, {"type": "line", "speaker": "主人", "text": "我能体会。我知道爸爸不敢睡觉，不是你的错。感觉世界没有声音也没有颜色，只剩你一个人了？不会的，宝贝。现在不怕，主人陪着你呢。梦到什么了呀？眼泪怎么又掉下来了，这样眼睛会哭坏的。不着急，慢慢说。梦到我不回来了？傻孩子，主人一定不会丢下宝宝一个人的。"}, {"type": "narr", "text": "她抽噎着说对不起。他摇头，语气带着不容置疑的温柔。"}, {"type": "line", "speaker": "主人", "text": "嗯，就算和上次一样，因为工作或其他原因，需要出门比较久——我也一定会在和宝宝约定的时间回来。为什么要说对不起？宝宝没有给我添麻烦，这个星期啊——宝贝已经很勇敢、很坚强，每天都努力照顾自己，不让主人担心。但是你这样……手怎么了？伸过来我看看。没什么就伸过来，另一只也伸过来。"}, {"type": "narr", "text": "他握住她的手，看着那一道道渗血的压印，声音涩住了。"}, {"type": "line", "speaker": "主人", "text": "手上压印全都是，不光这几个伤口还渗着血，还说没什么？我都不知道你压得这么厉害，疼不疼？还摇头。你这样子，说不疼，却一点力气都没有。主人知道，我的宝宝不是故意的，已经很努力想控制自己了。今天没打算烦你。可是宝贝啊，主人希望你知道，我的宝宝是很优秀、很优秀的小朋友。所以你可以再相信自己一点，相信自己能留在主人身边。你这个样子，我看了真的好心疼好心疼。"}, {"type": "narr", "text": "他站起身，语气放轻。她立刻攥住他的衣角，跟着站起来。他回头，无奈又心软地笑了。"}, {"type": "line", "speaker": "主人", "text": "好好待着，我去给你拿冰块。拿个冰块，一分钟，一分钟就回来，好吧，乖。还是跟过来了，小傻瓜。主人不会不见的，来，坐过来。给你敷上。我去把你衣角抚平，你到椅子上去，乖乖坐着，听到了没？眼睛里都是血丝，还一眨不眨地盯着我看。等酒喝完，乖乖把药吃了，然后和主人一起，好好吃一会儿。醒来以后我还在，保证宝宝一睁眼，真的就能看见我，好不好？"}, {"type": "narr", "text": "她终于放松下来，靠在他肩上，呼吸渐渐平稳。他低头，在她发顶落下一个吻。这个伤痕累累却努力活着的宝贝，他会用一辈子，把她护在怀里。"}]}, {"no": 76, "id": "uTa_sZLg-U0", "title": "【Lの女性向音声】你喜欢我吗", "title_zh": "你喜欢我吗", "duration": "00:06:36", "link": "https://www.youtube.com/watch?v=uTa_sZLg-U0", "enriched": true, "lines": [{"ts": "00:00:00", "text": "我，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "想，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "喝，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "你的，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "水。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:16", "text": "你身边有水吗？", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:00:18", "text": "借我喝点。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "我刚打球回来，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:24", "text": "没时间买水了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:27", "text": "我可渴了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "我不想喝他们的，我就想喝你的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "你杯子好好看啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:38", "text": "上面还有个标志，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:43", "text": "Meister什么的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:49", "text": "给，下次我再帮你接。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "再帮你接。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:10", "text": "水杯给我。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:01:13", "text": "走了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:16", "text": "这个水杯也太小了，够喝吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:01:19", "text": "改天我给你换个大的，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:22", "text": "换一个我们打球时候带的那种。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:26", "text": "今天小打一场，一打一。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:29", "text": "他们三个人拉着我打车轮战，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:33", "text": "然后，全被我打趴下了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "怎么样，厉害吧？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:40", "text": "不过还有一场。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:44", "text": "明天晚上，我来。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:47", "text": "训练之前没准备。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:50", "text": "你要不要来看。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "人不多。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:56", "text": "训练赛都没有什么人看，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:01:59", "text": "你过来给我们撑撑场面，", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:02:02", "text": "然后给我加油。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:02:05", "text": "不然打着都没意思。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:08", "text": "不用买水，你人来了就行。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "我会多跟教练说，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:16", "text": "让他在教练席旁边给你留个位置。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:20", "text": "好吧？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:25", "text": "害怕啥呀，他又不坐着。", "speaker": "他", "tone": "撒娇", "sound": []}, {"ts": "00:02:29", "text": "他明天就跑来跑去，你当裁判。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:33", "text": "你就这么定了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:02:37", "text": "你不准放我鸽子。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:02:42", "text": "不准放我鸽子。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:03:02", "text": "兄弟，你看到刚才坐那边那个女孩子了吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:09", "text": "他走了吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:16", "text": "看到她去哪儿了吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:03:23", "text": "好，谢谢。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "你怎么进来的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "这是男更衣室。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "你怎么跑进来的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "你刚刚藏哪儿了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:42", "text": "我进来之前没看到你了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:45", "text": "他们都没发现你啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:52", "text": "你还问我怎么回来这么晚。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:55", "text": "我一转头看你人就没了，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:03:58", "text": "我找了一圈都没找到你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "我哪知道你在这儿蹲着。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "傻瓜吗你。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "比赛都开始了，你也没回去啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "我知道那是什么事吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:04:12", "text": "我怕什么？", "speaker": "他", "tone": "温柔", "sound": []}, {"ts": "00:04:15", "text": "我就说我训练呗。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "你，你会怎么说。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "问我什么？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "对，要去集训三个月，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:31", "text": "就与上周定的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "那自然会知道的，不用特意说吧。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:41", "text": "你听小菲这么说的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:46", "text": "我换衣服了，你要看着吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:04:51", "text": "其实你想看也没关系，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:53", "text": "反正我也不用换裤子。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:56", "text": "我去集训的话，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:04:58", "text": "三个月不能回来，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:01", "text": "封闭训练，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:04", "text": "然后也不能用手机，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "就联系不到你了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:09", "text": "你会想我吗？", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:05:12", "text": "昨天说不喜欢我，", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:05:14", "text": "今天说想我。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "所以你到底喜不喜欢我。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:05:19", "text": "不准跑。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:05:22", "text": "给我转过来。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:05:25", "text": "我昨天可都听到了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:28", "text": "再问一遍。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:31", "text": "你到底喜不喜欢我。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:05:35", "text": "你不想说话的话，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:40", "text": "你点头也可以。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "那你以后就是我的了。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:05:47", "text": "小傻瓜。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:50", "text": "我们。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:53", "text": "咱们不会叫事老宝。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:56", "text": "在这儿都待会儿。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:05:59", "text": "我好饿。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:02", "text": "我为了找你，", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:05", "text": "饭都没吃呢。", "speaker": "他", "tone": "询问", "sound": []}, {"ts": "00:06:08", "text": "你过来，过来坐这边。", "speaker": "他", "tone": "命令", "sound": []}, {"ts": "00:06:11", "text": "我找点吃的。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:14", "text": "什么也没有？", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:19", "text": "你买什么了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "小饼加蛋啊！", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "你趁刚才跑去买这个了。", "speaker": "他", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "喜欢喜欢喜欢。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:06:24", "text": "最喜欢了。", "speaker": "他", "tone": "宠溺", "sound": []}, {"ts": "00:06:24", "text": "最可爱。", "speaker": "他", "tone": "平静", "sound": []}], "scene": "一位热爱打球的男生与（暧昧/暗恋中的）女生之间的青春日常互动。情境起点是男生打完球回来向女生讨水喝，两人以轻松调侃的口吻聊天——男生让女生明天去看自己训练、顺带发现女生一直躲着没见人。整体基调是甜宠、带点占有欲的暧昧日常；剧情主题为「确认心意/吃醋试探」，含轻度暧昧互动，无露骨内容。", "behaviors": [{"desc": "男生打完球回来讨水，提到想和女生多待会儿而非和队友"}, {"desc": "男生把水杯递给女生，约定下次再帮她接水"}, {"desc": "男生提议给女生换个大点的水杯，方便打球时带"}, {"desc": "男生邀请女生明天来看自己训练、当啦啦队加油"}, {"desc": "男生发现女生藏起来，质问她怎么进来的、刚藏哪儿了"}, {"desc": "男生告知即将封闭训练三个月、不能联系，问女生会不会想他"}, {"desc": "男生点破女生昨天说不喜欢、今天说想，追问到底喜不喜欢他"}, {"desc": "男生说饿了找吃的，发现女生买了小饼加蛋，开心地说最喜欢"}], "tone_summary": "（自动）他视角独白，语气以平静、命令、询问为主，题材偏现代情侣。", "genre_tags": ["现代情侣"], "genre_main": "现代情侣", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被他倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "自习室的角落里，她正低头看书。一个身影带着汗味走过来，在她面前停下，弯下腰，喘着气，一字一字地说。"}, {"type": "line", "speaker": "他", "text": "我，想，喝，你的，水。你身边有水吗？借我喝点。我刚打球回来，没时间买水了。我可渴了。我不想喝他们的，我就想喝你的。"}, {"type": "narr", "text": "她愣了一下，还没来得及反应，他已经拿起她的水杯喝了一口。喝完还端详着杯身，语气带着点孩子气的认真。"}, {"type": "line", "speaker": "他", "text": "你杯子好好看啊！上面还有个标志，Meister什么的。给，下次我再帮你接。再帮你接。水杯给我。走了。"}, {"type": "narr", "text": "他走了两步，又折回来，皱了皱眉。"}, {"type": "line", "speaker": "他", "text": "这个水杯也太小了，够喝吗？改天我给你换个大的，换一个我们打球时候带的那种。"}, {"type": "narr", "text": "他忽然又想起什么，眼睛一亮，语气带着邀功的得意。"}, {"type": "line", "speaker": "他", "text": "今天小打一场，一打一。他们三个人拉着我打车轮战，然后，全被我打趴下了。怎么样，厉害吧？不过还有一场。明天晚上，我来。训练之前没准备。"}, {"type": "narr", "text": "他顿了顿，声音低了些，带着点小心翼翼的试探。"}, {"type": "line", "speaker": "他", "text": "你要不要来看。人不多。训练赛都没有什么人看，你过来给我们撑撑场面，然后给我加油。不然打着都没意思。不用买水，你人来了就行。我会多跟教练说，让他在教练席旁边给你留个位置。好吧？"}, {"type": "narr", "text": "她刚想开口，他又抢着说下去，像是怕她拒绝。"}, {"type": "line", "speaker": "他", "text": "害怕啥呀，他又不坐着。他明天就跑来跑去，你当裁判。你就这么定了。你不准放我鸽子。不准放我鸽子。"}, {"type": "narr", "text": "第二天比赛结束后，他满头大汗地冲进更衣室，却没看见她。他拉住一个队友，语气带着着急。"}, {"type": "line", "speaker": "他", "text": "兄弟，你看到刚才坐那边那个女孩子了吗？他走了吗？看到她去哪儿了吗？好，谢谢。"}, {"type": "narr", "text": "他在更衣室找了一圈，最后在角落里看见蹲着的人。他愣了一下，气也不是笑也不是。"}, {"type": "line", "speaker": "他", "text": "你怎么进来的。这是男更衣室。你怎么跑进来的。你刚刚藏哪儿了。我进来之前没看到你了。他们都没发现你啊！"}, {"type": "narr", "text": "她抬起头，小声说，看他比赛结束没回来，就找过来了。他蹲下来，语气带着无奈又藏不住的高兴。"}, {"type": "line", "speaker": "他", "text": "你还问我怎么回来这么晚。我一转头看你人就没了，我找了一圈都没找到你。我哪知道你在这儿蹲着。傻瓜吗你。比赛都开始了，你也没回去啊！"}, {"type": "narr", "text": "他忽然想到什么，语气变得认真起来，带着一点忐忑。"}, {"type": "line", "speaker": "他", "text": "我知道那是什么事吗？我怕什么？我就说我训练呗。你，你会怎么说。问我什么？对，要去集训三个月，就与上周定的。那自然会知道的，不用特意说吧。你听小菲这么说的。"}, {"type": "narr", "text": "她低着头，攥着衣角。他看着她，忽然语气带着点故意的轻松，转移话题。"}, {"type": "line", "speaker": "他", "text": "我换衣服了，你要看着吗？其实你想看也没关系，反正我也不用换裤子。我去集训的话，三个月不能回来，封闭训练，然后也不能用手机，就联系不到你了。你会想我吗？"}, {"type": "line", "speaker": "他", "text": "昨天说不喜欢我，今天说想我。所以你到底喜不喜欢我。不准跑。给我转过来。我昨天可都听到了。再问一遍。你到底喜不喜欢我。你不想说话的话，你点头也可以。"}, {"type": "narr", "text": "她被他拉住，跑不掉，只好低着头，过了很久，才轻轻点了一下头。他愣了一瞬，随即眼睛亮起来，嘴角怎么也压不住。"}, {"type": "line", "speaker": "他", "text": "那你以后就是我的了。小傻瓜。我们。咱们不会叫事老宝。在这儿都待会儿。我好饿。我为了找你，饭都没吃呢。你过来，过来坐这边。我找点吃的。什么也没有？你买什么了。"}, {"type": "narr", "text": "她红着脸，从包里掏出一个小饼加蛋。他愣了一下，随即接过来，咬了一大口，含糊不清地说着话，眼睛却一直看着她。"}, {"type": "line", "speaker": "他", "text": "小饼加蛋啊！你趁刚才跑去买这个了。喜欢喜欢喜欢。最喜欢了。最可爱。"}, {"type": "narr", "text": "更衣室的灯有些暗，他蹲在她对面，大口吃着饼，眼睛亮得像有星星。她看着他，也忍不住弯起嘴角。那一句“你到底喜不喜欢我”，终于有了答案。"}]}, {"no": 77, "id": "r3Nc7OeBDYg", "title": "【Lの女性向音声】你在主人面前，百无禁忌", "title_zh": "你在主人面前，百无禁忌", "duration": "00:09:02", "link": "https://www.youtube.com/watch?v=r3Nc7OeBDYg", "enriched": true, "lines": [{"ts": "00:00:01", "text": "先起来吧。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:03", "text": "来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:06", "text": "站着。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:09", "text": "怎么了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:12", "text": "不满意？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "今天不是你心心念念的做苦趣吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:18", "text": "抬头。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:21", "text": "看着我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:24", "text": "说话。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:28", "text": "行。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "不想说就算了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:33", "text": "过来躺下。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:37", "text": "要不是自始。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:42", "text": "马上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:47", "text": "双手抱膝。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "核心收紧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:53", "text": "腿伸直并拢。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:56", "text": "紧张什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:59", "text": "跟你揉揉。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:02", "text": "刚刚，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "不是都疼哭了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:08", "text": "还没有。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:11", "text": "还嘴硬。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:14", "text": "也不知道是谁哭着喊着说，", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:01:17", "text": "我不要了，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:20", "text": "我马上就疼死了。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:01:23", "text": "好了好了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:27", "text": "自食其果。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "主人要欣赏一下我今晚的作品。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:36", "text": "小屁股肿起来了一层。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:39", "text": "从藤痕，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:42", "text": "到藤条。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:45", "text": "颜色均匀。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "最后藤条抽着几下，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:51", "text": "红痕交错的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:54", "text": "我还真是个艺术家。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:58", "text": "你也要看？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "手机给我，拍给你。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:08", "text": "这么喜欢看，", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:02:11", "text": "那以后都到镜子面前来罚吧，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "让你看着自己的样子。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "好不好？", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:02:22", "text": "像什么东西。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "你说不要，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:29", "text": "但是身体却很诚实。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:32", "text": "这个地方，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "比刚才拍照的时候，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:38", "text": "流得更厉害了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:41", "text": "这是轻轻一碰就抖起来了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:45", "text": "我的小狗狗是发情了。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:02:49", "text": "没有主人的允许，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "一次都不许去。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:57", "text": "忍着。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:02", "text": "小玩具在狗狗的穴穴里，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:04", "text": "前后滑一滑，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:07", "text": "然后时不时地，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:10", "text": "碰一下。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:13", "text": "小豆豆。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:16", "text": "认真。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:19", "text": "手。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:22", "text": "抱着腿。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:26", "text": "小屁股往哪儿躲？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "自己撞回来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:43", "text": "这就受不了了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "那可不行。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:51", "text": "狗狗竟敢违反主人的命令，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "私自高潮。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:01", "text": "知道错了就好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:04", "text": "既然是小妹妹犯了错，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:07", "text": "让屁股替她挨打，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:10", "text": "是不是不合适？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:13", "text": "对，分开。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:16", "text": "手抓住脚腕。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "很好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "小惩大诫。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:28", "text": "姿势保持好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:32", "text": "动了我们就重新来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "打开。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:42", "text": "手。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:49", "text": "再挤下小巴掌就喊疼。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:04:53", "text": "既然不乖，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:57", "text": "那就用马鞭好了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:01", "text": "怎么还跪起来了？", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:07", "text": "过来过来过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:12", "text": "主人可不记得，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:15", "text": "给过你拒绝的权利。的权利。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "所以该罚的一下都不会少。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "怕疼看着。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:24", "text": "怕。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:26", "text": "可以是你逃避惩罚的理由吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:05:29", "text": "你不仅是怕疼，", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:31", "text": "也怕我，", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:34", "text": "怕我弄伤你。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:05:36", "text": "所以不敢把自己全身心地交给我。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:39", "text": "对主人不信任。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:42", "text": "既然这样，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:45", "text": "我们这段关系就到这儿吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "好吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:05:51", "text": "我们可以做回普通情侣。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:54", "text": "哥哥，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:57", "text": "也不再打你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:00", "text": "给你足够的安全感。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:03", "text": "好不好？", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:06:06", "text": "起来吧，不跪了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:09", "text": "听话。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:06:12", "text": "来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:15", "text": "哥哥给你擦擦眼泪。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:19", "text": "叫我主人。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:22", "text": "还想做主人啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:25", "text": "那你信任我吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:06:28", "text": "信任不只是说而已，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:32", "text": "你要付出行动的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:36", "text": "要。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:42", "text": "果然还是要教育一下，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:48", "text": "才会自己把自己摆好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:54", "text": "开始。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:00", "text": "开始。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:06", "text": "疼吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:10", "text": "记住了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:15", "text": "主人给揉揉。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "急什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:30", "text": "又想要了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:07:33", "text": "今天这种不乖，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:36", "text": "不给了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:39", "text": "什么叫打完了？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "刚才罚的是你乱动，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:46", "text": "一码归一码。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:49", "text": "我好心饶了你，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:52", "text": "你非要点火是不是？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:56", "text": "你要。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:58", "text": "就是认错还挺快的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:01", "text": "不管心里怎么想的，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:03", "text": "嘴上先认错。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "是吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:09", "text": "哥哥。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:12", "text": "过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:08:16", "text": "准抱抱你。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:08:19", "text": "疼什么？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:08:23", "text": "过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:08:27", "text": "最近有什么不顺心的事吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:33", "text": "今天晚上，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:36", "text": "打一打了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:39", "text": "可以哭了。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:08:42", "text": "还不听话的去得一次。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:08:45", "text": "现在感觉好点了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:08:48", "text": "哥哥今天做得很好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "义务让人释放压力。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "要不要。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "下次，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "可以再大胆一些。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "你在主人面前，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:48", "text": "百无禁忌。", "speaker": "主人", "tone": "平静", "sound": []}], "scene": "主人与「小狗狗」（顺从者）之间的管娇情景剧。情境起点是主人让顺从者起身、躺下接受管娇，依剧情有体罚与训诫；中途主人提出若不信任则可退回普通情侣关系。整体基调是支配/服从的角色扮演，剧情主题为「管娇与信任的建立」，含体罚情节与轻度管娇描写（无露骨细节）。", "behaviors": [{"desc": "主人让顺从者起身站立，询问是否对今日安排不满"}, {"desc": "主人命令顺从者躺下，要求其摆出规定姿势"}, {"desc": "主人对管娇后的作品表示满意，用手机拍照"}, {"desc": "主人指出顺从者身体反应，强调需主人允许"}, {"desc": "顺从者违规，主人令其改正姿势并继续管娇"}, {"desc": "主人察觉顺从者因害怕而抗拒，提出可退回普通情侣关系"}, {"desc": "顺从者确认仍愿称主人为主人、表示信任"}, {"desc": "管娇结束后主人转为温柔安抚，关心顺从者近况并让其释放压力"}], "tone_summary": "（自动）主人视角独白，语气以平静、命令、温柔为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "治愈", "敏感"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "高（含敏感/控制元素）", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": ["鞭", "发情", "惩罚"], "sensitive": true, "tier": "auto", "story": [{"type": "narr", "text": "房间里安静下来。她趴在他腿上，眼圈红红的。他放下手里的藤条，语气带着一点心软。"}, {"type": "line", "speaker": "主人", "text": "先起来吧。来，站着。怎么了？不满意？今天不是你心心念念的做苦趣吗？抬头，看着我。说话。行，不想说就算了。过来躺下。要不是自始，马上。双手抱膝，核心收紧，腿伸直并拢。紧张什么？跟你揉揉。刚刚，不是都疼哭了吗？"}, {"type": "narr", "text": "她别过头，小声说还没有。他挑了挑眉，语气带着促狭。"}, {"type": "line", "speaker": "主人", "text": "还没有？还嘴硬。也不知道是谁哭着喊着说，我不要了，我马上就疼死了。好了好了，自食其果。主人要欣赏一下我今晚的作品。小屁股肿起来了一层，从藤痕到藤条，颜色均匀，最后藤条抽的那几下，红痕交错。我还真是个艺术家。"}, {"type": "narr", "text": "她红着脸，小声说想看。他拿起手机，语气带着一点逗弄。"}, {"type": "narr", "text": "她别过头，耳根发烫。他看着她，语气带着了然的笑意，却没有继续逗她。"}, {"type": "line", "speaker": "主人", "text": "行了，逗你的。身体倒是很诚实。主人说过什么？没有主人的允许，一次都不许。忍着。手抱着腿，小屁股往哪儿躲？自己撞回来。这就受不了了？那可不行。狗狗竟敢违反主人的命令——知道错了就好。既然是小妹妹犯了错，让屁股替她挨打，是不是不合适？"}, {"type": "narr", "text": "她红着脸趴好，声音带着哭腔。他看着她，语气带着不容违抗的命令。"}, {"type": "line", "speaker": "主人", "text": "对，分开。手抓住脚腕。很好。小惩大诫。姿势保持好，动了我们就重新来。打开。手。再挤下小巴掌就喊疼？既然不乖，那就用马鞭好了。怎么还跪起来了？过来过来过来。主人可不记得，给过你拒绝的权利。所以该罚的一下都不会少。"}, {"type": "narr", "text": "她跪在地上，眼泪终于掉下来。他看着她，声音忽然低下来，带着认真的分量。"}, {"type": "line", "speaker": "主人", "text": "怕疼看着。怕——可以是你逃避惩罚的理由吗？你不仅是怕疼，也怕我，怕我弄伤你。所以不敢把自己全身心地交给我。对主人不信任。既然这样，我们这段关系就到这儿吧，好吗？我们可以做回普通情侣。哥哥，也不再打你。给你足够的安全感，好不好？"}, {"type": "narr", "text": "她猛地抬头，眼泪一下子涌出来，拼命摇头。他看着她，没有立刻心软，只是继续说。"}, {"type": "line", "speaker": "主人", "text": "起来吧，不跪了。听话，来。哥哥给你擦擦眼泪。叫我主人。还想做主人啊！那你信任我吗？信任不只是说而已，你要付出行动的。要。果然还是要教育一下，才会自己把自己摆好。开始。开始。疼吗？记住了吗？主人给揉揉。"}, {"type": "narr", "text": "她趴在他腿上，抽噎着，声音带着软软的委屈。他低头看着她，语气带着无奈的纵容。"}, {"type": "line", "speaker": "主人", "text": "急什么？又想要了？今天这种不乖，不给了。什么叫打完了？刚才罚的是你乱动，一码归一码。我好心饶了你，你非要点火是不是？你要？就是认错还挺快的，不管心里怎么想的，嘴上先认错，是吧？哥哥。过来，准抱抱你。疼什么？过来。"}, {"type": "narr", "text": "她扑进他怀里，把脸埋进他胸口。他一下一下拍着她的背，声音温柔下来。"}, {"type": "line", "speaker": "主人", "text": "最近有什么不顺心的事吧。今天晚上，打一打了。可以哭了。还不听话地再来一次？现在感觉好点了吗？哥哥今天做得很好，义务让人释放压力。要不要，下次可以再大胆一些。你在主人面前，百无禁忌。"}, {"type": "narr", "text": "她靠在他怀里，终于慢慢止住了眼泪。他低头亲了亲她的发顶，语气带着纵容的笑意。那一句“百无禁忌”，是信任，也是承诺。而她知道的——从今天起，她可以把自己，完完整整地交给他。"}]}, {"no": 78, "id": "gFlJC7nGFLE", "title": "【Lの女性向音声】你是我的安眠药", "title_zh": "你是我的安眠药", "duration": "00:08:18", "link": "https://www.youtube.com/watch?v=gFlJC7nGFLE", "enriched": true, "lines": [{"ts": "00:00:00", "text": "这么晚了还不睡，是在等我吧？", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:00:13", "text": "睡不着？想主人了？那今晚陪你玩点更刺激的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:26", "text": "玩什么？等会儿你就知道了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:39", "text": "是什么？待会儿你就知道了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:52", "text": "小狗狗，只要你开口要，主人就给你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:05", "text": "过来，两只手往前伸，手腕并拢。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:19", "text": "现在，趴好，屁股翘起来，等着主人过来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "还问为什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "你看看这个姿势，标准吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:38", "text": "主人说过，这个姿势，要一丝不挂，连睡裙都不许留。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "穿着睡裙，什么意思？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "手被绑住了脱不了？那是在等主人帮你脱？", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:38", "text": "没有？那需要主人帮忙吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:38", "text": "需要的话，应该说什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "快，转过来，跪直，把胸挺起来，让主人看看。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:01:38", "text": "给狗狗把衣服剪出两个洞。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "好了，这样好看多了。让主人拍下来，好好看看你。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:01:38", "text": "看看，是不是很好看。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "不过，我还能让狗狗更好看，就像这样。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "现在左边，明显比右边好看多了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "现在右边更红一点，那就再给左边补补色。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "好像还是不行。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "狗狗刚刚数没数？两边各挨了多少下？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "左边再打三下，你确定？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "既然你这么自信，那等下要是不对称，主人可就要罚你了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:01:38", "text": "还是不对称，这只小狗狗可要受罚了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:01:38", "text": "已经湿成这样了，什么时候开始的？是趴着等的时候，还是被主人打的时候？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "是自己一个人跪趴在这儿等主人的时候，被拍的时候，还是刚刚被打的时候？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "在厨房就被主人绑住了，你可真是个小骚货，早就在等这一刻了吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "现在过来，用你的嘴服侍主人。服侍舒服了，今晚才有得享受，懂吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:38", "text": "注意你的舌头，含深一点，再深一点。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "等一下，主人又想到了个好玩的，狗狗把手举高。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:01:38", "text": "眼睛蒙上，看不见，身体反而更诚实。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "好了，继续吧，主人要把你最美的时候都记下来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "刚刚拍的照片为什么要删呀！", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:01:38", "text": "脸红什么？我都不害羞，你倒害羞了。不过今晚，主人可不会这么轻易放过你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:38", "text": "该睡了，乖，安眠药已经喝完了，明天还要早起呢。", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:38", "text": "这么快就睡着了？看来是被主人折腾累了。", "speaker": "主人", "tone": "平静", "sound": []}], "scene": "主人与「狗狗」之间的睡前情景。情境起点是深夜主人见狗狗不睡，提议玩点什么，布置跪趴等姿势并拍照；过程中穿插管娇与调侃。整体基调是带有管娇色彩的睡前互动与安抚，剧情主题为「哄睡/管娇游戏」，含轻度管娇情节（无露骨细节）。", "behaviors": [{"desc": "主人见狗狗深夜未睡，提议陪它玩点什么，并让其双手前伸"}, {"desc": "主人命令狗狗摆出跪趴等待的姿势"}, {"desc": "主人检查姿势是否标准，借机给狗狗拍照记录"}, {"desc": "主人因左右不对称而提出罚，并让狗狗服侍自己"}, {"desc": "互动结束，主人让狗狗喝完东西去睡，狗狗很快睡着"}], "tone_summary": "（自动）主人视角独白，语气以平静、询问、撒娇为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": ["绑"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "夜深了，她还窝在沙发上不肯睡。他走过去，语气带着了然的笑意。"}, {"type": "line", "speaker": "主人", "text": "这么晚了还不睡，是在等我吧？睡不着？想主人了？那今晚陪你玩点更刺激的。玩什么？等会儿你就知道了。是什么？待会儿你就知道了。小狗狗，只要你开口要，主人就给你。过来，两只手往前伸，手腕并拢。"}, {"type": "narr", "text": "她乖乖伸出手，手腕被他用丝带轻轻绑住。他指了指床沿，语气带着不容拒绝的从容。"}, {"type": "narr", "text": "她乖乖伸出手，手腕被丝带轻轻绑住。他指了指床沿，语气带着不容拒绝的从容。"}, {"type": "line", "speaker": "主人", "text": "现在，趴好，屁股翘起来，等着主人过来。还问为什么？你看看这个姿势，标准吗？主人说过，这个姿势，要一丝不挂，连睡裙都不许留。穿着睡裙，什么意思？手被绑住了脱不了？那是在等主人帮你脱？没有？那需要主人帮忙吗？需要的话，应该说什么？"}, {"type": "narr", "text": "她红着脸，小声说出那句请求。他低笑，蹲下身替她解开，指尖擦过她发烫的耳尖。气氛一点点升温，他却不急，慢慢布置着这一晚的节奏。"}, {"type": "line", "speaker": "主人", "text": "快，转过来，跪直，把胸挺起来，让主人看看。给狗狗把衣服剪出两个洞。好了，这样好看多了。让主人拍下来，好好看看你。看看，是不是很好看。不过，我还能让狗狗更好看，就像这样。现在左边，明显比右边好看多了。现在右边更红一点，那就再给左边补补色。好像还是不行。狗狗刚刚数没数？两边各挨了多少下？左边再打三下，你确定？既然你这么自信，那等下要是不对称，主人可就要罚你了。还是不对称，这只小狗狗可要受罚了。"}, {"type": "narr", "text": "她咬着唇，呼吸乱得厉害。他停下来，指尖轻轻擦过她腿侧，声音带着了然的笑意。"}, {"type": "narr", "text": "她的呼吸早已乱了，指尖攥紧床单，整个人烧得发烫。他却不急不缓地掌控着节奏，直到她再也撑不住，声音带着哭腔求饶。"}, {"type": "line", "speaker": "主人", "text": "等一下，主人又想到了个好玩的，狗狗把手举高。眼睛蒙上，看不见，身体反而更诚实。好了，继续吧，主人要把你最美的时候都记下来。刚刚拍的照片为什么要删呀！脸红什么？我都不害羞，你倒害羞了。不过今晚，主人可不会这么轻易放过你。"}, {"type": "narr", "text": "这一夜的账，直到她彻底没了力气才算完。他把她搂进怀里，替她盖好被子，语气温柔下来。"}, {"type": "line", "speaker": "主人", "text": "该睡了，乖，安眠药已经喝完了，明天还要早起呢。这么快就睡着了？看来是被主人折腾累了。"}, {"type": "narr", "text": "她在他怀里，呼吸渐渐均匀，像一只终于被哄睡的猫。夜很静，而他轻轻拍着她的背，等着她沉入梦乡。这一剂安眠药，效果很好。"}]}, {"no": 79, "id": "L0oMkZBrBNc", "title": "【Lの女性向音声】你是我触手可及，却未感品尝的珍宝", "title_zh": "你是我触手可及，却未感品尝的珍宝", "duration": "00:07:55", "link": "https://www.youtube.com/watch?v=L0oMkZBrBNc", "enriched": true, "lines": [{"ts": "00:00:00", "text": "你是我求回来的流浪猫。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:03", "text": "是我花了时间，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "花了精力，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:10", "text": "费力拯救、", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:14", "text": "悉心照料的珍宝。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:17", "text": "如果不是别无选择，", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:00:21", "text": "我怎么忍心让你离开呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:00:31", "text": "醒了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:35", "text": "起来吃早饭。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:00:40", "text": "我买了小笼包和烧卖。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:45", "text": "想吃什么？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:50", "text": "好。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "都放桌上了。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:01:00", "text": "是不是又没穿内衣啊？", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:01:05", "text": "什么都看到了？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:09", "text": "回去穿上。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:13", "text": "不许上手。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:01:17", "text": "穿上再过来。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:01:21", "text": "去。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:25", "text": "吃饭吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:31", "text": "不行。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:37", "text": "喝豆浆给我。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:01:44", "text": "等吃完饭，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:48", "text": "吃完饭我送你回家吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:01:55", "text": "不回家呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:01:57", "text": "我送你回学校。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:00", "text": "学校应该有你宿舍吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "回宿舍住吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:06", "text": "我联系你老师了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "一会儿送你到学校门口，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:12", "text": "有人会接你的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:15", "text": "东西我都帮你收拾好了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:18", "text": "我不是要赶你走啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:22", "text": "你也不能一直住我这里吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:26", "text": "也不方便。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:30", "text": "我不觉得你是累赘。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:35", "text": "你听我说。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:40", "text": "我虽然收留你，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "让你在这儿住几天，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:45", "text": "但是这毕竟不是你的家呀！", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:02:47", "text": "我也不能一直照顾你啊！", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:50", "text": "我不是你可以依赖的人。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:53", "text": "回学校好好上课。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:55", "text": "不要再逃课了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:02:58", "text": "不要再喝酒。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:00", "text": "不要再大晚上在外面晃荡。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:03", "text": "保护好自己。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:06", "text": "别让我再看到你又被谁欺负了。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:13", "text": "乖一点。", "speaker": "老师", "tone": "撒娇", "sound": []}, {"ts": "00:03:21", "text": "别哭了。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:24", "text": "老师给我来消息了。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:03:27", "text": "他们在那边等你，走吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "我从来不踏入任何感情中。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:35", "text": "从来不擅长处理任何复杂的情绪。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:41", "text": "我不能教你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:44", "text": "你也不能在我身边，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:47", "text": "寻求慰藉。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:50", "text": "我做不到。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "我是失败的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:56", "text": "至少曾经是。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:03:59", "text": "我保护不了任何人。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "你怎么回来了？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:24", "text": "你又喝酒了是不是？", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:04:27", "text": "别抱我。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:04:30", "text": "我说了别抱我。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:04:33", "text": "对我生气了我非常生气。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:37", "text": "怎么就不长记性呢？", "speaker": "老师", "tone": "询问", "sound": []}, {"ts": "00:04:41", "text": "学校里没人会管你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:43", "text": "所以你把自己喝成这样。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "然后大半夜又跑出来。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:04:48", "text": "万一遇到坏人怎么办。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:50-00:04:52", "text": "万一又像上次。", "speaker": "老师", "tone": "责备", "sound": []}, {"ts": "00:04:55", "text": "还是你本来就故意挑男人。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:04:57", "text": "装成楚楚可怜的样子。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:05:00", "text": "等别人心软。", "speaker": "老师", "tone": "命令", "sound": []}, {"ts": "00:05:03", "text": "把你带回家为所欲为。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:06", "text": "如果你再这样下去的话。", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:05:08", "text": "不要再这么做了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:10", "text": "我是老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:13", "text": "你清楚我的身份。", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:05:15", "text": "我不会对你做任何。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:18", "text": "超出师生关系的事情。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:20", "text": "我也没有义务教你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:22", "text": "我也没有义务保护你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "因为你根本就不是我的学生。", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:05:27", "text": "你只是我在路边遇到，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:30", "text": "一个隔壁学校的女孩，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:32", "text": "被陌生人救起。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:34", "text": "我好心救了你。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "除此之外，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:39", "text": "我们没有任何关系。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:42", "text": "我也没有对你，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:48", "text": "有任何应该负的责任。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:54", "text": "照顾你只是顺便。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:05:58", "text": "收留你也是，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:01", "text": "因为这边正好有房间。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:05", "text": "不要多想。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:09", "text": "你现在这样子要去哪儿。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:13", "text": "你去哪儿。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "什么叫不关我的事？", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:06:21", "text": "如果不关我的事，", "speaker": "老师", "tone": "宠溺", "sound": []}, {"ts": "00:06:25", "text": "你为什么回来找我。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:29", "text": "让我还可可怜怜地，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:33", "text": "蹲在家门口等我。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:37", "text": "回来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "我让你回来。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:45", "text": "你就知道我会心软对不对？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:49", "text": "为什么一定要送你离开？", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:06:55", "text": "因为你不知道，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:02", "text": "又知道我有多害怕，", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:07:06", "text": "做出这样的事情。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:14", "text": "威胁老师。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:16", "text": "是的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:18", "text": "她在我这儿。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:20", "text": "安全的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:22", "text": "你放心吧。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:24", "text": "我会照顾好她的。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:27", "text": "明早我送她去上课。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "不好意思麻烦你了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:35-00:07:38", "text": "辛苦了。", "speaker": "老师", "tone": "温柔", "sound": []}, {"ts": "00:07:42", "text": "您早点休息。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:46", "text": "所以你现在，", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:51", "text": "是我需要负责的责任了。", "speaker": "老师", "tone": "平静", "sound": []}, {"ts": "00:07:51", "text": "就是。", "speaker": "老师", "tone": "平静", "sound": []}], "scene": "一位自称「老师」的男性收留了一个被救的、隔壁学校的女孩（以流浪猫作比），照顾几天后想送她回学校，女孩醉酒跑回来黏着他。老师表面冷漠推拒，强调两人无特殊关系、自己不擅长感情，但最终还是心软收留并承诺照顾。整体基调是「口嫌体正直」的守护与克制，剧情主题为「收留与推拒/心软」，含醉酒与轻度情感拉扯，无露骨内容。", "behaviors": [{"desc": "男子以流浪猫比喻，称自己救回并照料了女孩"}, {"desc": "男子叫醒女孩吃早饭，提醒她穿好衣服再来"}, {"desc": "男子提议送女孩回学校宿舍，称不能一直收留"}, {"desc": "男子叮嘱女孩别再喝酒、保护好自己，随后因她醉酒跑回而生气"}, {"desc": "女孩醉酒回来抱男子，男子生气质问并强调自己只是老师、两人无关系"}, {"desc": "男子嘴上说收留只是顺便，却仍让女孩进门等候"}, {"desc": "男子向电话那头的老师确认女孩在他这里安全"}, {"desc": "男子最终承认自己对女孩负有照看责任"}], "tone_summary": "（自动）老师视角独白，语气以平静、命令、责备为主，题材偏校园/师生。", "genre_tags": ["校园/师生", "治愈"], "genre_main": "校园", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被老师倾诉/照顾/管教的一方（你）", "signature_elements": [], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "清晨的光落进客厅。他站在餐桌边，摆好刚买的小笼包和烧卖，目光落在卧室门口那个还睡眼惺忪的身影上，语气带着一点无奈。"}, {"type": "line", "speaker": "老师", "text": "醒了？起来吃早饭。我买了小笼包和烧卖，想吃什么？好，都放桌上了。你是我求回来的流浪猫，是我花了时间、花了精力，费力拯救、悉心照料的珍宝。如果不是别无选择，我怎么忍心让你离开呢？"}, {"type": "narr", "text": "她站在原地，被他那句\"珍宝\"说得晃了神。他却没有再看她，转身去盛豆浆，声音平平的。"}, {"type": "line", "speaker": "老师", "text": "是不是又没穿内衣啊？什么都看到了？回去穿上。不许上手，穿上再过来。去。"}, {"type": "narr", "text": "她低头看了看自己身上那件宽大的T恤，脸一红，转身钻进房间。他望着她消失的背影，轻轻叹了口气。"}, {"type": "narr", "text": "她换好衣服出来，安静地坐下吃饭。他看着她，终于把在心里想了一夜的话说了出来，语气尽量平淡。"}, {"type": "line", "speaker": "老师", "text": "吃饭吧。不行，豆浆给我。等吃完饭，我送你回家吧。不回家呢？我送你回学校。学校应该有你宿舍吧，回宿舍住吧。我联系你老师了，一会儿送你到学校门口，有人会接你的。东西我都帮你收拾好了。"}, {"type": "narr", "text": "她握着筷子的手顿住，眼眶一下子红了。他别开视线，声音却还是稳的。"}, {"type": "line", "speaker": "老师", "text": "我不是要赶你走啊！你也不能一直住我这里吧，也不方便。我不觉得你是累赘，你听我说。我虽然收留你，让你在这儿住几天，但是这毕竟不是你的家呀！我也不能一直照顾你啊！我不是你可以依赖的人。"}, {"type": "narr", "text": "她的眼泪啪嗒啪嗒掉进碗里。他停下筷子，终究还是叹了口气，把话说得更软了些。"}, {"type": "line", "speaker": "老师", "text": "回学校好好上课，不要再逃课了。不要再喝酒，不要再大晚上在外面晃荡。保护好自己，别让我再看到你又被谁欺负了。乖一点，别哭了。你老师给我来消息了，他们在那边等你，走吧。"}, {"type": "narr", "text": "她终于被送走了。他回到空荡荡的家里，站在窗前很久。那句\"珍宝\"是他真心说的，可他知道，自己从来不是能留住谁的人。"}, {"type": "line", "speaker": "老师", "text": "我从来不踏入任何感情中，从来不擅长处理任何复杂的情绪。我不能教你，你也不能在我身边寻求慰藉。我做不到。我是失败的，至少曾经是。我保护不了任何人。"}, {"type": "narr", "text": "他以为这段交集就这样结束了。可深夜的门铃，把一切都打乱了。他拉开门，看见她红着眼眶蹲在门口，身上带着酒气，立刻沉了脸色。"}, {"type": "line", "speaker": "老师", "text": "你怎么回来了？你又喝酒了是不是？别抱我。我说了别抱我。对我生气了我非常生气。怎么就不长记性呢？学校里没人会管你，所以你把自己喝成这样，然后大半夜又跑出来。万一遇到坏人怎么办，万一又像上次——还是你本来就故意挑男人，装成楚楚可怜的样子，等别人心软，把你带回家为所欲为？"}, {"type": "narr", "text": "她被他骂得眼泪直掉，却倔强地站在原地，不肯走。他看着她这副模样，声音终于低下来，带着疲惫。"}, {"type": "line", "speaker": "老师", "text": "如果你再这样下去的话，不要再这么做了。我是老师，你清楚我的身份。我不会对你做任何超出师生关系的事情。我也没有义务教你，我也没有义务保护你。因为你根本就不是我的学生。你只是我在路边遇到，一个隔壁学校的女孩，被陌生人救起。我好心救了你，除此之外，我们没有任何关系。"}, {"type": "narr", "text": "她听完，整个人像被抽空了力气，转身就要走。他下意识地伸手，拉住了她的手腕。她回头，眼里全是水光。"}, {"type": "line", "speaker": "老师", "text": "你现在这样子要去哪儿？你去哪儿？什么叫不关我的事？如果不关我的事，你为什么回来找我？让我还可可怜怜地，蹲在家门口等我。回来。我让你回来。你就知道我会心软，对不对？"}, {"type": "narr", "text": "她被他拽回来，踉跄着撞进他怀里，眼泪终于决堤。他僵了一瞬，手还是轻轻落在她背上。电话铃忽然响起，他看了一眼屏幕，语气平静下来。"}, {"type": "line", "speaker": "老师", "text": "为什么一定要送你离开？因为你不知道，我有多害怕自己做出这样的事情。威胁老师？是的。她在我这儿，安全的，你放心吧。我会照顾好她的，明早我送她去上课。不好意思麻烦你了，辛苦了，您早点休息。"}, {"type": "narr", "text": "他挂断电话，低头看着怀里那个哭得一塌糊涂的人，沉默了许久。窗外的夜色很深，他终于伸手，替她擦掉脸上的泪。"}, {"type": "line", "speaker": "老师", "text": "所以你现在，是我需要负责的责任了。就是。"}, {"type": "narr", "text": "她在他怀里抬起头，泪眼朦胧地看着他。他别开脸，耳根却悄悄红了。那句\"珍宝\"，这一次，他终于认了下来。她不是流浪猫了，是他捡回来、要负责到底的人。"}]}, {"no": 80, "id": "n71C0Hj1sTk", "title": "【Lの女性向音声】你是这世界上最棒、最独一无二的存在", "title_zh": "你是这世界上最棒、最独一无二的存在", "duration": "00:08:36", "link": "https://www.youtube.com/watch?v=n71C0Hj1sTk", "enriched": true, "lines": [{"ts": "00:00:00", "text": "你真的确定要我这样对你吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:03", "text": "好吧。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:07", "text": "既然你坚持，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:11", "text": "那我今天就满足你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:15", "text": "跪下。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:00:19", "text": "主人之前说听到命令的反应时间是多少？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:30", "text": "太快了没反应过来，这是理由吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:00:35", "text": "在这儿好好跪着等我回来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:41", "text": "不要乱动。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:48", "text": "不然后果你知道。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:00:55", "text": "自己把这个放进去。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:01", "text": "眼罩戴上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:07", "text": "往前爬。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:12", "text": "放心。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:17", "text": "主人牵着你呢。", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:23", "text": "牵着你呢。", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:01:29", "text": "好听。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:34", "text": "跪爬在沙发上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:39", "text": "屁股撅高点。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:46", "text": "再翘。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:53", "text": "多少？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:01:58", "text": "就要看狗狗自己的表现了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:03", "text": "不错。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:09", "text": "乱动什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:19", "text": "还动就别怪我不客气了。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:28", "text": "这条大了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:31", "text": "怎么这么没用啊？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:34", "text": "不可以。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:37", "text": "求求主人啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:02:42", "text": "不准。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:02:58", "text": "真的忍不住了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:17", "text": "喷出来了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:21", "text": "我允许了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:03:25", "text": "对不起有什么用。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:30", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:33", "text": "我想怎样就怎样是吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:36", "text": "那既然狗狗都这么说了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:39", "text": "转过来。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:03:42", "text": "脚放在沙发上。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:46", "text": "对，打开。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:49", "text": "再打开。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:03:53", "text": "别乱动。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:04:02", "text": "不然的话，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:06", "text": "有你受的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:11", "text": "好了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:14", "text": "来，我闻。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:17", "text": "自己的味道，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:20", "text": "喜欢吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:04:23", "text": "说话。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:27", "text": "原来是一只。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:30", "text": "喜欢闻自己骚味的小母狗。", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:33", "text": "张嘴。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:36", "text": "舔一舔。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:39", "text": "既然喜欢，", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:04:42", "text": "就好好感受感受。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:45", "text": "现在。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:48", "text": "边舔。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:51", "text": "边把下面东西拿出来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:04:54", "text": "快点。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:04:58", "text": "继续。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:07", "text": "狗狗可真笨。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:10", "text": "竟然又滑进去了。", "speaker": "主人", "tone": "责备", "sound": []}, {"ts": "00:05:14", "text": "帮你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:17", "text": "狗狗不弄出来的话，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:21", "text": "主人是不会停的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:25", "text": "眼罩摘下来。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:29", "text": "不准闭眼。", "speaker": "主人", "tone": "命令", "sound": []}, {"ts": "00:05:33", "text": "仔细看着自己，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:37", "text": "是怎么被主人玩弄的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:05:42", "text": "喜欢这样被主人玩吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:05:47", "text": "很喜欢什么？", "speaker": "主人", "tone": "宠溺", "sound": []}, {"ts": "00:05:54", "text": "小骚货。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:03", "text": "想要什么？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:07", "text": "好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:12", "text": "都给你。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:17", "text": "舒服了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:24", "text": "那能和我说说，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:29", "text": "今天发生了什么事吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:06:35", "text": "你今天那么反常，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:41", "text": "我还能看不出来啊！", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:47", "text": "我知道你已经很用心了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:06:53", "text": "没有得到想要的成绩。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:01", "text": "哪有什么做得不好？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:07", "text": "想不通，觉得委屈。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:13", "text": "那为什么都不和我说呢？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:18", "text": "什么叫麻烦我？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:23", "text": "怕打扰我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:25", "text": "我会嫌你烦，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:28", "text": "然后不要你了。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:31", "text": "傻瓜呀！", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:07:34", "text": "你知道吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:07:37", "text": "我从来都不觉得你说的话、", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:40", "text": "做的事会麻烦到我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:43", "text": "而且我很希望，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:46", "text": "你能依赖我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:49", "text": "虽然你总觉得自己做得不够好，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:51", "text": "可是在我眼里，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:53", "text": "你是这个世界上最棒、", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:56", "text": "最独一无二的存在。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:07:58", "text": "你不需要对自己要求那么高的。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:01", "text": "只要我们比之前进步一点点，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:03", "text": "就是成长。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:06", "text": "对不对？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:08", "text": "哎呦。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:10", "text": "怎么又哭了？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:08:13", "text": "不哭不哭。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:08:15", "text": "怎么又哭了？", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:08:18", "text": "我抱抱果然是水做的。", "speaker": "主人", "tone": "撒娇", "sound": []}, {"ts": "00:08:20", "text": "刚刚哭这么久还没够。", "speaker": "主人", "tone": "温柔", "sound": []}, {"ts": "00:08:23", "text": "好好。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "都怪我。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "好吧？", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "休息够了吗？", "speaker": "主人", "tone": "询问", "sound": []}, {"ts": "00:08:23", "text": "我先帮你去洗澡。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "然后我们，", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "好好地睡觉。", "speaker": "主人", "tone": "平静", "sound": []}, {"ts": "00:08:23", "text": "好不好？", "speaker": "主人", "tone": "撒娇", "sound": []}], "scene": "主人与「小狗狗」的管娇情景，前半段为支配/服从的角色扮演与管娇，后半段转为温柔关怀——主人察觉狗狗今日反常，引导它说出因成绩不理想而自我否定，并给予肯定与安慰。整体基调是「严厉管娇+情感接纳」，剧情主题为「管娇后安抚/自我价值肯定」，含体罚与亲密互动（非露骨）。", "behaviors": [{"desc": "主人确认狗狗想要被如此对待，令其跪下"}, {"desc": "主人让狗狗自行放入物品、戴眼罩，牵着它爬行"}, {"desc": "主人令狗狗跪趴在沙发上，调整姿势"}, {"desc": "管娇中狗狗失控，主人质问「我允许了吗」"}, {"desc": "主人让狗狗自我观察、感受"}, {"desc": "主人问狗狗是否喜欢这样被对待"}, {"desc": "主人察觉狗狗今日反常，引导它说出心事"}, {"desc": "主人安慰狗狗，称它是世上最棒最独一无二的存在，并帮其洗澡安睡"}], "tone_summary": "（自动）主人视角独白，语气以平静、询问、命令为主，题材偏主仆/调教。", "genre_tags": ["主仆/调教", "治愈"], "genre_main": "主仆/调教", "emotion_arc": "（自动）平静", "intensity": "中", "listener_role": "（自动）被主人倾诉/照顾/管教的一方（你）", "signature_elements": ["跪下"], "sensitive": false, "tier": "auto", "story": [{"type": "narr", "text": "客厅的光线调得很暗。她跪在地毯上，垂着眼睛，指尖不安地绞着衣角。他在她面前站定，低头看了她很久，声音带着一点不容商量的意味。"}, {"type": "line", "speaker": "主人", "text": "你真的确定要我这样对你吗？好吧。既然你坚持，那我今天就满足你。跪下。"}, {"type": "narr", "text": "她顺从地跪好。他伸出手，她自觉地低下头，眼罩落下来，世界陷入一片柔软的黑。他牵着她，一步步慢慢往前走。"}, {"type": "line", "speaker": "主人", "text": "主人之前说听到命令的反应时间是多少？太快了没反应过来，这是理由吗？在这儿好好跪着等我回来。不要乱动。不然后果你知道。自己把这个放进去。眼罩戴上。往前爬。放心。主人牵着你呢。牵着你呢。好听。"}, {"type": "narr", "text": "黑暗里，她只听得见他的脚步声，和他落在耳边的低语。他把她安置在沙发边，一下一下，不算重，却每一下都让她绷紧。"}, {"type": "line", "speaker": "主人", "text": "跪爬在沙发上。屁股撅高点。再翘。多少？就要看狗狗自己的表现了。不错。乱动什么？还动就别怪我不客气了。这条大了。怎么这么没用啊？不可以。求求主人啊！不准。真的忍不住了。"}, {"type": "narr", "text": "她咬着唇，努力不发出声音。他在身后停了一会儿，忽然叹了口气，语气缓下来，带着一丝无奈。"}, {"type": "line", "speaker": "主人", "text": "喷出来了。我允许了吗？对不起有什么用。好。我想怎样就怎样是吧？那既然狗狗都这么说了。转过来。脚放在沙发上。对，打开。再打开。别乱动。不然的话，有你受的。好了。来，我闻。自己的味道，喜欢吗？说话。"}, {"type": "narr", "text": "她别开脸，耳根烧得通红。他看了一会儿，终于松开手，语气里带着一点了然的笑意。"}, {"type": "line", "speaker": "主人", "text": "原来是一只。喜欢闻自己骚味的小母狗。张嘴。舔一舔。既然喜欢，就好好感受感受。现在。边舔。边把下面东西拿出来。快点。继续。狗狗可真笨。竟然又滑进去了。帮你。狗狗不弄出来的话，主人是不会停的。眼罩摘下来。不准闭眼。仔细看着自己，是怎么被主人玩弄的。喜欢这样被主人玩吗？很喜欢什么？小骚货。想要什么？好。都给你。舒服了。"}, {"type": "narr", "text": "房间里安静下来，只剩下她细细的喘息。他却没有急着离开，而是坐到她身边，把她散乱的头发别到耳后，声音忽然轻下来，像是换了一个人。"}, {"type": "line", "speaker": "主人", "text": "那能和我说说，今天发生了什么事吗？你今天那么反常，我还能看不出来啊！我知道你已经很用心了。没有得到想要的成绩。哪有什么做得不好？想不通，觉得委屈。"}, {"type": "narr", "text": "她低着头，眼泪吧嗒吧嗒掉在地毯上。她以为那些情绪藏得很好，原来他全都看在眼里。"}, {"type": "line", "speaker": "主人", "text": "那为什么都不和我说呢？什么叫麻烦我？怕打扰我。我会嫌你烦，然后不要你了。傻瓜呀！你知道吗？我从来都不觉得你说的话、做的事会麻烦到我。而且我很希望，你能依赖我。"}, {"type": "line", "speaker": "主人", "text": "虽然你总觉得自己做得不够好，可是在我眼里，你是这个世界上最棒、最独一无二的存在。你不需要对自己要求那么高的。只要我们比之前进步一点点，就是成长。对不对？"}, {"type": "narr", "text": "她再也忍不住，扑进他怀里哭出声来。他接住她，一下一下拍着她的背，声音又轻又软，带着心疼。"}, {"type": "line", "speaker": "主人", "text": "哎呦。怎么又哭了？不哭不哭。怎么又哭了？我抱抱果然是水做的。刚刚哭这么久还没够。好好。都怪我。好吧？"}, {"type": "line", "speaker": "主人", "text": "休息够了吗？我先帮你去洗澡。然后我们，好好地睡觉。好不好？"}]}]);